structs.RegexToken:
typedef struct _RegexToken
{
    uint8_t kind;
    uint8_t mode;
    uint16_t count_lo;
    uint16_t count_hi;
    uint16_t mask[16];
    int16_t pair_offset;
} RegexToken;

structs.RegexMatcherState:
typedef struct _RegexMatcherState
{
    uint32_t k;
    uint32_t group_state;
    uint32_t prev;
    uint64_t i;
    uint64_t range_min;
    uint64_t range_max;
} RegexMatcherState;

functions.regex_parse:
static inline int regex_parse(const char *pattern, RegexToken *tokens, int16_t *token_count, int32_t flags)
{
    int64_t tokens_len = *token_count;
    uint64_t pattern_len = strlen(pattern);
    if (token_count == 0)
        return -2;
    int esc_state = 0;
    const int STATE_NORMAL = 1;
    const int STATE_QUANT = 2;
    const int STATE_MODE = 3;
    const int STATE_CC_INIT = 4;
    const int STATE_CC_NORMAL = 5;
    const int STATE_CC_RANGE = 6;
    int state = STATE_NORMAL;
    int char_class_mem = -1;
    RegexToken token;
    {
        memset(&(token), 0, sizeof(RegexToken));
        token.count_lo = 1;
        token.count_hi = 2;
    };
    int16_t k = 0;
    token.kind = REMIMU_KIND_OPEN;
    token.count_lo = 0;
    token.count_hi = 0;
    int paren_count = 0;
    for (uint64_t i = 0; i < pattern_len; i++)
    {
        char c = pattern[i];
        if (state == STATE_QUANT)
        {
            state = STATE_MODE;
            if (c == '?')
            {
                token.count_lo = 0;
                token.count_hi = 2;
                continue;
            }
            else if (c == '+')
            {
                token.count_lo = 1;
                token.count_hi = 0;
                continue;
            }
            else if (c == '*')
            {
                token.count_lo = 0;
                token.count_hi = 0;
                continue;
            }
            else if (c == '{')
            {
                if (pattern[i + 1] == 0 || pattern[i + 1] < '0' || pattern[i + 1] > '9')
                    state = STATE_NORMAL;
                else
                {
                    i += 1;
                    uint32_t val = 0;
                    while (pattern[i] >= '0' && pattern[i] <= '9')
                    {
                        val *= 10;
                        val += (uint32_t)(pattern[i] - '0');
                        if (val > 0xFFFF)
                        {
                            puts("quantifier range too long");
                            return -1;
                        }
                        i += 1;
                    }
                    token.count_lo = val;
                    token.count_hi = val + 1;
                    if (pattern[i] == ',')
                    {
                        token.count_hi = 0;
                        i += 1;
                        if (pattern[i] >= '0' && pattern[i] <= '9')
                        {
                            uint32_t val2 = 0;
                            while (pattern[i] >= '0' && pattern[i] <= '9')
                            {
                                val2 *= 10;
                                val2 += (uint32_t)(pattern[i] - '0');
                                if (val2 > 0xFFFF)
                                {
                                    puts("quantifier range too long");
                                    return -1;
                                }
                                i += 1;
                            }
                            if (val2 < val)
                            {
                                puts("quantifier range is backwards");
                                return -1;
                            }
                            token.count_hi = val2 + 1;
                        }
                    }
                    if (pattern[i] == '}')
                    {
                        continue;
                    }
                    else
                    {
                        puts("quantifier range syntax broken (no terminator)");
                        return -1;
                    }
                }
            }
        }
        if (state == STATE_MODE)
        {
            state = STATE_NORMAL;
            if (c == '?')
            {
                token.mode |= REMIMU_MODE_LAZY;
                continue;
            }
            else if (c == '+')
            {
                token.mode |= REMIMU_MODE_POSSESSIVE;
                continue;
            }
        }
        if (state == STATE_NORMAL)
        {
            if (esc_state == 1)
            {
                esc_state = 0;
                if (c == 'n')
                {
                    token.mask[((uint8_t)('\n')) >> 4] |= 1 << ((uint8_t)('\n') & 0xF);
                }
                else if (c == 'r')
                {
                    token.mask[((uint8_t)('\r')) >> 4] |= 1 << ((uint8_t)('\r') & 0xF);
                }
                else if (c == 't')
                {
                    token.mask[((uint8_t)('\t')) >> 4] |= 1 << ((uint8_t)('\t') & 0xF);
                }
                else if (c == 'v')
                {
                    token.mask[((uint8_t)('\v')) >> 4] |= 1 << ((uint8_t)('\v') & 0xF);
                }
                else if (c == 'f')
                {
                    token.mask[((uint8_t)('\f')) >> 4] |= 1 << ((uint8_t)('\f') & 0xF);
                }
                else if (c == 'x')
                {
                    if (pattern[i + 1] == 0 || pattern[i + 2] == 0)
                        return -1;
                    uint8_t n0 = pattern[i + 1];
                    uint8_t n1 = pattern[i + 1];
                    if (n0 < '0' || n0 > 'f' || n1 < '0' || n1 > 'f' || (n0 > '9' && n0 < 'A') ||
                        (n1 > '9' && n1 < 'A'))
                        return -1;
                    if (n0 > 'F')
                        n0 -= 0x20;
                    if (n1 > 'F')
                        n1 -= 0x20;
                    if (n0 >= 'A')
                        n0 -= 'A' - 10;
                    if (n1 >= 'A')
                        n1 -= 'A' - 10;
                    n0 -= '0';
                    n1 -= '0';
                    {
                        token.mask[((uint8_t)((n1 << 4) | n0)) >> 4] |= 1 << ((uint8_t)((n1 << 4) | n0) & 0xF);
                    }
                    i += 2;
                }
                else if (c == '{' || c == '}' || c == '[' || c == ']' || c == '-' || c == '(' || c == ')' || c == '|' ||
                         c == '^' || c == '$' || c == '*' || c == '+' || c == '?' || c == ':' || c == '.' || c == '/' ||
                         c == '\\')
                {
                    {
                        token.mask[((uint8_t)(c)) >> 4] |= 1 << ((uint8_t)(c) & 0xF);
                    }
                    state = STATE_QUANT;
                }
                else if (c == 'd' || c == 's' || c == 'w' || c == 'D' || c == 'S' || c == 'W')
                {
                    uint8_t is_upper = c <= 'Z';
                    uint16_t m[16];
                    memset(m, 0, sizeof(m));
                    if (is_upper)
                        c += 0x20;
                    if (c == 'd' || c == 'w')
                        m[3] |= 0x03FF;
                    if (c == 's')
                    {
                        m[0] |= 0x3E00;
                        m[2] |= 1;
                    }
                    if (c == 'w')
                    {
                        m[4] |= 0xFFFE;
                        m[5] |= 0x87FF;
                        m[6] |= 0xFFFE;
                        m[7] |= 0x07FF;
                    }
                    for (int i = 0; i < 16; i++)
                        token.mask[i] |= is_upper ? ~m[i] : m[i];
                    token.kind = REMIMU_KIND_NORMAL;
                    state = STATE_QUANT;
                }
                else if (c == 'b')
                {
                    token.kind = REMIMU_KIND_BOUND;
                    state = STATE_NORMAL;
                }
                else if (c == 'B')
                {
                    token.kind = REMIMU_KIND_NBOUND;
                    state = STATE_NORMAL;
                }
                else
                {
                    puts("unsupported escape sequence");
                    return -1;
                }
            }
            else
            {
                {
                    if (k == 0 || tokens[k - 1].kind != token.kind ||
                        (token.kind != REMIMU_KIND_BOUND && token.kind != REMIMU_KIND_NBOUND))
                    {
                        if (token.mode & REMIMU_MODE_INVERTED)
                        {
                            for (int n = 0; n < 16; n++)
                                token.mask[n] = ~token.mask[n];
                            token.mode &= ~REMIMU_MODE_INVERTED;
                        }
                        if (k >= tokens_len)
                        {
                            puts("buffer overflow");
                            return -2;
                        }
                        tokens[k++] = token;
                        {
                            memset(&(token), 0, sizeof(RegexToken));
                            token.count_lo = 1;
                            token.count_hi = 2;
                        };
                    }
                }
                if (c == '\\')
                {
                    esc_state = 1;
                }
                else if (c == '[')
                {
                    state = STATE_CC_INIT;
                    char_class_mem = -1;
                    token.kind = REMIMU_KIND_NORMAL;
                    if (pattern[i + 1] == '^')
                    {
                        token.mode |= REMIMU_MODE_INVERTED;
                        i += 1;
                    }
                }
                else if (c == '(')
                {
                    paren_count += 1;
                    state = STATE_NORMAL;
                    token.kind = REMIMU_KIND_OPEN;
                    token.count_lo = 0;
                    token.count_hi = 1;
                    if (pattern[i + 1] == '?' && pattern[i + 2] == ':')
                    {
                        token.kind = REMIMU_KIND_NCOPEN;
                        i += 2;
                    }
                    else if (pattern[i + 1] == '?' && pattern[i + 2] == '>')
                    {
                        token.kind = REMIMU_KIND_NCOPEN;
                        {
                            if (k == 0 || tokens[k - 1].kind != token.kind ||
                                (token.kind != REMIMU_KIND_BOUND && token.kind != REMIMU_KIND_NBOUND))
                            {
                                if (token.mode & REMIMU_MODE_INVERTED)
                                {
                                    for (int n = 0; n < 16; n++)
                                        token.mask[n] = ~token.mask[n];
                                    token.mode &= ~REMIMU_MODE_INVERTED;
                                }
                                if (k >= tokens_len)
                                {
                                    puts("buffer overflow");
                                    return -2;
                                }
                                tokens[k++] = token;
                                {
                                    memset(&(token), 0, sizeof(RegexToken));
                                    token.count_lo = 1;
                                    token.count_hi = 2;
                                };
                            }
                        }
                        state = STATE_NORMAL;
                        token.kind = REMIMU_KIND_NCOPEN;
                        token.mode = REMIMU_MODE_POSSESSIVE;
                        token.count_lo = 1;
                        token.count_hi = 2;
                        i += 2;
                    }
                }
                else if (c == ')')
                {
                    paren_count -= 1;
                    if (paren_count < 0 || k == 0)
                        return -1;
                    token.kind = REMIMU_KIND_CLOSE;
                    state = STATE_QUANT;
                    int balance = 0;
                    ptrdiff_t found = -1;
                    for (ptrdiff_t l = k - 1; l >= 0; l--)
                    {
                        if (tokens[l].kind == REMIMU_KIND_NCOPEN || tokens[l].kind == REMIMU_KIND_OPEN)
                        {
                            if (balance == 0)
                            {
                                found = l;
                                break;
                            }
                            else
                                balance -= 1;
                        }
                        else if (tokens[l].kind == REMIMU_KIND_CLOSE)
                            balance += 1;
                    }
                    if (found == -1)
                        return -1;
                    ptrdiff_t diff = k - found;
                    if (diff > 32767)
                        return -1;
                    token.pair_offset = -diff;
                    tokens[found].pair_offset = diff;
                    if (tokens[found].mode == REMIMU_MODE_POSSESSIVE)
                    {
                        {
                            if (k == 0 || tokens[k - 1].kind != token.kind ||
                                (token.kind != REMIMU_KIND_BOUND && token.kind != REMIMU_KIND_NBOUND))
                            {
                                if (token.mode & REMIMU_MODE_INVERTED)
                                {
                                    for (int n = 0; n < 16; n++)
                                        token.mask[n] = ~token.mask[n];
                                    token.mode &= ~REMIMU_MODE_INVERTED;
                                }
                                if (k >= tokens_len)
                                {
                                    puts("buffer overflow");
                                    return -2;
                                }
                                tokens[k++] = token;
                                {
                                    memset(&(token), 0, sizeof(RegexToken));
                                    token.count_lo = 1;
                                    token.count_hi = 2;
                                };
                            }
                        }
                        token.kind = REMIMU_KIND_CLOSE;
                        token.mode = REMIMU_MODE_POSSESSIVE;
                        token.pair_offset = -diff - 2;
                        tokens[found - 1].pair_offset = diff + 2;
                    }
                }
                else if (c == '?' || c == '+' || c == '*' || c == '{')
                {
                    puts("quantifier in non-quantifier context");
                    return -1;
                }
                else if (c == '.')
                {
                    {
                        for (int n = 0; n < 16; n++)
                            token.mask[n] = 0xFFFF;
                    };
                    if (flags & REMIMU_FLAG_DOT_NO_NEWLINES)
                    {
                        token.mask[1] ^= 0x04;
                        token.mask[1] ^= 0x20;
                    }
                    state = STATE_QUANT;
                }
                else if (c == '^')
                {
                    token.kind = REMIMU_KIND_CARET;
                    state = STATE_NORMAL;
                }
                else if (c == '$')
                {
                    token.kind = REMIMU_KIND_DOLLAR;
                    state = STATE_NORMAL;
                }
                else if (c == '|')
                {
                    token.kind = REMIMU_KIND_OR;
                    state = STATE_NORMAL;
                }
                else
                {
                    {
                        token.mask[((uint8_t)(c)) >> 4] |= 1 << ((uint8_t)(c) & 0xF);
                    };
                    state = STATE_QUANT;
                }
            }
        }
        else if (state == STATE_CC_INIT || state == STATE_CC_NORMAL || state == STATE_CC_RANGE)
        {
            if (c == '\\' && esc_state == 0)
            {
                esc_state = 1;
                continue;
            }
            uint8_t esc_c = 0;
            if (esc_state == 1)
            {
                esc_state = 0;
                if (c == 'n')
                    esc_c = '\n';
                else if (c == 'r')
                    esc_c = '\r';
                else if (c == 't')
                    esc_c = '\t';
                else if (c == 'v')
                    esc_c = '\v';
                else if (c == 'f')
                    esc_c = '\f';
                else if (c == 'x')
                {
                    if (pattern[i + 1] == 0 || pattern[i + 2] == 0)
                        return -1;
                    uint8_t n0 = pattern[i + 1];
                    uint8_t n1 = pattern[i + 1];
                    if (n0 < '0' || n0 > 'f' || n1 < '0' || n1 > 'f' || (n0 > '9' && n0 < 'A') ||
                        (n1 > '9' && n1 < 'A'))
                        return -1;
                    if (n0 > 'F')
                        n0 -= 0x20;
                    if (n1 > 'F')
                        n1 -= 0x20;
                    if (n0 >= 'A')
                        n0 -= 'A' - 10;
                    if (n1 >= 'A')
                        n1 -= 'A' - 10;
                    n0 -= '0';
                    n1 -= '0';
                    esc_c = (n1 << 4) | n0;
                    i += 2;
                }
                else if (c == '{' || c == '}' || c == '[' || c == ']' || c == '-' || c == '(' || c == ')' || c == '|' ||
                         c == '^' || c == '$' || c == '*' || c == '+' || c == '?' || c == ':' || c == '.' || c == '/' ||
                         c == '\\')
                {
                    esc_c = c;
                }
                else if (c == 'd' || c == 's' || c == 'w' || c == 'D' || c == 'S' || c == 'W')
                {
                    if (state == STATE_CC_RANGE)
                    {
                        puts("tried to use a shorthand as part of a range");
                        return -1;
                    }
                    uint8_t is_upper = c <= 'Z';
                    uint16_t m[16];
                    memset(m, 0, sizeof(m));
                    if (is_upper)
                        c += 0x20;
                    if (c == 'd' || c == 'w')
                        m[3] |= 0x03FF;
                    if (c == 's')
                    {
                        m[0] |= 0x3E00;
                        m[2] |= 1;
                    }
                    if (c == 'w')
                    {
                        m[4] |= 0xFFFE;
                        m[5] |= 0x87FF;
                        m[6] |= 0xFFFE;
                        m[7] |= 0x07FF;
                    }
                    for (int i = 0; i < 16; i++)
                        token.mask[i] |= is_upper ? ~m[i] : m[i];
                    char_class_mem = -1;
                    continue;
                }
                else
                {
                    printf("unknown/unsupported escape sequence in character class (\\%c)\n", c);
                    return -1;
                }
            }
            if (state == STATE_CC_INIT)
            {
                char_class_mem = c;
                {
                    token.mask[((uint8_t)(c)) >> 4] |= 1 << ((uint8_t)(c) & 0xF);
                };
                state = STATE_CC_NORMAL;
            }
            else if (state == STATE_CC_NORMAL)
            {
                if (c == ']' && esc_c == 0)
                {
                    char_class_mem = -1;
                    state = STATE_QUANT;
                    continue;
                }
                else if (c == '-' && esc_c == 0 && char_class_mem >= 0)
                {
                    state = STATE_CC_RANGE;
                    continue;
                }
                else
                {
                    char_class_mem = c;
                    {
                        token.mask[((uint8_t)(c)) >> 4] |= 1 << ((uint8_t)(c) & 0xF);
                    };
                    state = STATE_CC_NORMAL;
                }
            }
            else if (state == STATE_CC_RANGE)
            {
                if (c == ']' && esc_c == 0)
                {
                    char_class_mem = -1;
                    {
                        token.mask[((uint8_t)('-')) >> 4] |= 1 << ((uint8_t)('-') & 0xF);
                    };
                    state = STATE_QUANT;
                    continue;
                }
                else
                {
                    if (char_class_mem == -1)
                    {
                        puts("character class range is broken");
                        return -1;
                    }
                    if ((uint8_t)c < char_class_mem)
                    {
                        puts("character class range is misordered");
                        return -1;
                    }
                    for (uint8_t i = c; i > char_class_mem; i--)
                    {
                        token.mask[((uint8_t)(i)) >> 4] |= 1 << ((uint8_t)(i) & 0xF);
                    };
                    state = STATE_CC_NORMAL;
                    char_class_mem = -1;
                }
            }
        }
        else
            ((void)sizeof((0) ? 1 : 0), __extension__({
                 if (0)
                     ;
                 else
                     __assert_fail("0", "/home/bbzs/code/reporeflectrust/data/project/CBench/Remimu/my_regex.h", 694,
                                   __extension__ __PRETTY_FUNCTION__);
             }));
    }
    if (paren_count > 0)
    {
        puts("(paren_count > 0)");
        return -1;
    }
    if (esc_state != 0)
    {
        puts("(esc_state != 0)");
        return -1;
    }
    if (state >= STATE_CC_INIT)
    {
        puts("(state >= STATE_CC_INIT)");
        return -1;
    }
    {
        if (k == 0 || tokens[k - 1].kind != token.kind ||
            (token.kind != REMIMU_KIND_BOUND && token.kind != REMIMU_KIND_NBOUND))
        {
            if (token.mode & REMIMU_MODE_INVERTED)
            {
                for (int n = 0; n < 16; n++)
                    token.mask[n] = ~token.mask[n];
                token.mode &= ~REMIMU_MODE_INVERTED;
            }
            if (k >= tokens_len)
            {
                puts("buffer overflow");
                return -2;
            }
            tokens[k++] = token;
            {
                memset(&(token), 0, sizeof(RegexToken));
                token.count_lo = 1;
                token.count_hi = 2;
            };
        }
    }
    token.kind = REMIMU_KIND_CLOSE;
    token.count_lo = 1;
    token.count_hi = 2;
    {
        if (k == 0 || tokens[k - 1].kind != token.kind ||
            (token.kind != REMIMU_KIND_BOUND && token.kind != REMIMU_KIND_NBOUND))
        {
            if (token.mode & REMIMU_MODE_INVERTED)
            {
                for (int n = 0; n < 16; n++)
                    token.mask[n] = ~token.mask[n];
                token.mode &= ~REMIMU_MODE_INVERTED;
            }
            if (k >= tokens_len)
            {
                puts("buffer overflow");
                return -2;
            }
            tokens[k++] = token;
            {
                memset(&(token), 0, sizeof(RegexToken));
                token.count_lo = 1;
                token.count_hi = 2;
            };
        }
    };
    token.kind = REMIMU_KIND_END;
    {
        if (k == 0 || tokens[k - 1].kind != token.kind ||
            (token.kind != REMIMU_KIND_BOUND && token.kind != REMIMU_KIND_NBOUND))
        {
            if (token.mode & REMIMU_MODE_INVERTED)
            {
                for (int n = 0; n < 16; n++)
                    token.mask[n] = ~token.mask[n];
                token.mode &= ~REMIMU_MODE_INVERTED;
            }
            if (k >= tokens_len)
            {
                puts("buffer overflow");
                return -2;
            }
            tokens[k++] = token;
            {
                memset(&(token), 0, sizeof(RegexToken));
                token.count_lo = 1;
                token.count_hi = 2;
            };
        }
    };
    tokens[0].pair_offset = k - 2;
    tokens[k - 2].pair_offset = -(k - 2);
    *token_count = k;
    uint64_t n = 0;
    for (int16_t k2 = 0; k2 < k; k2++)
    {
        if (tokens[k2].kind == REMIMU_KIND_CLOSE)
        {
            tokens[k2].mask[0] = n++;
            int16_t k3 = k2 + tokens[k2].pair_offset;
            tokens[k3].count_lo = tokens[k2].count_lo;
            tokens[k3].count_hi = tokens[k2].count_hi;
            tokens[k3].mask[0] = n++;
            tokens[k3].mode = tokens[k2].mode;
            if (n > 1024)
                return -1;
        }
        else if (tokens[k2].kind == REMIMU_KIND_OR || tokens[k2].kind == REMIMU_KIND_OPEN ||
                 tokens[k2].kind == REMIMU_KIND_NCOPEN)
        {
            int balance = 0;
            ptrdiff_t found = -1;
            for (ptrdiff_t l = k2 + 1; l < tokens_len; l++)
            {
                if (tokens[l].kind == REMIMU_KIND_OR && balance == 0)
                {
                    found = l;
                    break;
                }
                else if (tokens[l].kind == REMIMU_KIND_CLOSE)
                {
                    if (balance == 0)
                    {
                        found = l;
                        break;
                    }
                    else
                        balance -= 1;
                }
                else if (tokens[l].kind == REMIMU_KIND_NCOPEN || tokens[l].kind == REMIMU_KIND_OPEN)
                    balance += 1;
            }
            if (found == -1)
            {
                puts("unbalanced parens...");
                return -1;
            }
            ptrdiff_t diff = found - k2;
            if (diff > 32767)
            {
                puts("too long...");
                return -1;
            }
            if (tokens[k2].kind == REMIMU_KIND_OR)
                tokens[k2].pair_offset = diff;
            else
                tokens[k2].mask[15] = diff;
        }
    }
    return 0;
}

functions.regex_match:
static inline int64_t regex_match(const RegexToken *tokens, const char *text, size_t start_i, uint16_t cap_slots,
                                  int64_t *cap_pos, int64_t *cap_span)
{
    (void)text;
    const uint8_t verbose = 0;
    const uint16_t stack_size_max = 1024;
    const uint16_t aux_stats_size = 1024;
    if (cap_slots > aux_stats_size)
        cap_slots = aux_stats_size;
    uint8_t q_group_accepts_zero[aux_stats_size];
    uint32_t q_group_state[aux_stats_size];
    uint32_t q_group_stack[aux_stats_size];
    uint16_t q_group_cap_index[aux_stats_size];
    memset(q_group_cap_index, 0xFF, sizeof(q_group_cap_index));
    uint64_t tokens_len = 0;
    uint32_t k = 0;
    uint16_t caps = 0;
    while (tokens[k].kind != REMIMU_KIND_END)
    {
