functions.print_regex_tokens:
static inline void print_regex_tokens(RegexToken *tokens)
{
    const char *kind_to_str[] = {
        "NORMAL", "OPEN", "NCOPEN", "CLOSE", "OR", "CARET", "DOLLAR", "BOUND", "NBOUND", "END",
    };
    const char *mode_to_str[] = {
        "GREEDY",
        "POSSESS",
        "LAZY",
    };
    for (int k = 0;; k++)
    {
        printf("%s\t%s\t", kind_to_str[tokens[k].kind], mode_to_str[tokens[k].mode]);
        int c_old = -1;
        for (int c = 0; c < (tokens[k].kind ? 0 : 256); c++)
        {
            if ((!!(tokens[k].mask[((uint8_t)c) >> 4] & (1 << ((uint8_t)c & 0xF)))))
            {
                if (c_old == -1)
                    c_old = c;
            }
            else if (c_old != -1)
            {
                if (c - 1 == c_old)
                {
                    {
                        if (c_old >= 0x20 && c_old <= 0x7E)
                            printf("%c", c_old);
                        else
                            printf("\\x%02x", c_old);
                    }
                    c_old = -1;
                }
                else if (c - 2 == c_old)
                {
                    {
                        if (c_old >= 0x20 && c_old <= 0x7E)
                            printf("%c", c_old);
                        else
                            printf("\\x%02x", c_old);
                    }
                    {
                        if (c_old + 1 >= 0x20 && c_old + 1 <= 0x7E)
                            printf("%c", c_old + 1);
                        else
                            printf("\\x%02x", c_old + 1);
                    }
                    c_old = -1;
                }
                else
                {
                    {
                        if (c_old >= 0x20 && c_old <= 0x7E)
                            printf("%c", c_old);
                        else
                            printf("\\x%02x", c_old);
                    }
                    printf("-");
                    {
                        if (c - 1 >= 0x20 && c - 1 <= 0x7E)
                            printf("%c", c - 1);
                        else
                            printf("\\x%02x", c - 1);
                    }
                    c_old = -1;
                }
            }
        }
        printf("\t{%d,%d}\t(%d)\n", tokens[k].count_lo, tokens[k].count_hi - 1, tokens[k].pair_offset);
        if (tokens[k].kind == REMIMU_KIND_END)
            break;
    }
